// Act-based integration harness.
//
// Per the task requirements, the workflow's behaviour is validated end-to-end
// through `act` (not by invoking the script directly). For each test case we:
//   1. Build an isolated temp git repo containing the project + that case's
//      fixture data (fixtures/secrets.json).
//   2. Run `act push --rm`, capturing all output.
//   3. Append the output to act-result.txt (clearly delimited).
//   4. Assert act exited 0, every job "succeeded", and the workflow produced
//      the EXACT expected summary counts for that fixture.
//
// Run with: bun run run-act-tests.ts
import { spawnSync } from "node:child_process";
import {
  cpSync,
  existsSync,
  mkdtempSync,
  rmSync,
  writeFileSync,
  appendFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const PROJECT_ROOT = import.meta.dir;
const RESULT_FILE = join(PROJECT_ROOT, "act-result.txt");

interface TestCase {
  name: string;
  /** Fixture written to fixtures/secrets.json for this case. */
  fixture: unknown;
  /** Exact expected summary line the workflow must emit (NOW pinned to 2026-06-27). */
  expectedSummary: string;
}

// All cases assume the workflow's pinned NOW=2026-06-27 and WARNING_DAYS=14.
const CASES: TestCase[] = [
  {
    name: "mixed-urgencies",
    fixture: {
      secrets: [
        { name: "db-password", lastRotated: "2026-06-01", rotationPolicyDays: 90, requiredBy: ["api", "worker"] },
        { name: "stripe-api-key", lastRotated: "2026-04-08", rotationPolicyDays: 90, requiredBy: ["billing"] },
        { name: "legacy-token", lastRotated: "2026-01-01", rotationPolicyDays: 90, requiredBy: ["legacy-sync"] },
        { name: "tls-cert", lastRotated: "2025-06-01", rotationPolicyDays: 365, requiredBy: ["gateway"] },
      ],
    },
    expectedSummary: "ROTATION_SUMMARY total=4 expired=2 warning=1 ok=1",
  },
  {
    name: "all-ok",
    fixture: [
      { name: "fresh-a", lastRotated: "2026-06-20", rotationPolicyDays: 90, requiredBy: ["api"] },
      { name: "fresh-b", lastRotated: "2026-06-01", rotationPolicyDays: 90, requiredBy: [] },
    ],
    expectedSummary: "ROTATION_SUMMARY total=2 expired=0 warning=0 ok=2",
  },
  {
    name: "all-expired",
    fixture: [
      { name: "old-a", lastRotated: "2026-01-01", rotationPolicyDays: 30, requiredBy: ["x"] },
      { name: "old-b", lastRotated: "2025-01-01", rotationPolicyDays: 90, requiredBy: ["y"] },
      { name: "old-c", lastRotated: "2026-03-01", rotationPolicyDays: 30, requiredBy: ["z"] },
    ],
    expectedSummary: "ROTATION_SUMMARY total=3 expired=3 warning=0 ok=0",
  },
];

// Project files copied into each isolated temp repo.
const COPY_ITEMS = ["src", "scripts", "tests", ".github", "package.json", "tsconfig.json", ".actrc"];

function setupRepo(testCase: TestCase): string {
  const dir = mkdtempSync(join(tmpdir(), `act-srv-${testCase.name}-`));
  for (const item of COPY_ITEMS) {
    const from = join(PROJECT_ROOT, item);
    if (existsSync(from)) {
      cpSync(from, join(dir, item), { recursive: true });
    }
  }
  // Write this case's fixture as the file the workflow reads.
  writeFileSync(
    join(dir, "fixtures", "secrets.json"),
    JSON.stringify(testCase.fixture, null, 2),
  );

  // act requires a git repo with at least one commit.
  const git = (...args: string[]) =>
    spawnSync("git", args, { cwd: dir, encoding: "utf8" });
  git("init", "-q");
  git("config", "user.email", "ci@example.com");
  git("config", "user.name", "ci");
  git("add", "-A");
  git("commit", "-q", "-m", "test fixture");
  return dir;
}

let failures = 0;

// Truncate the result file at the start of a run.
writeFileSync(RESULT_FILE, `# act integration results — ${CASES.length} cases\n`);

for (const testCase of CASES) {
  console.log(`\n=== Running act for case: ${testCase.name} ===`);
  const dir = setupRepo(testCase);

  const result = spawnSync(
    "act",
    ["push", "--rm", "-W", ".github/workflows/secret-rotation-validator.yml"],
    { cwd: dir, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 },
  );

  const output = (result.stdout ?? "") + "\n" + (result.stderr ?? "");
  const delimiter =
    `\n${"=".repeat(70)}\n` +
    `TEST CASE: ${testCase.name}\n` +
    `expected: ${testCase.expectedSummary}\n` +
    `act exit code: ${result.status}\n` +
    `${"=".repeat(70)}\n`;
  appendFileSync(RESULT_FILE, delimiter + output + "\n");

  // --- Assertions ---
  const problems: string[] = [];
  if (result.status !== 0) {
    problems.push(`act exited with code ${result.status} (expected 0)`);
  }
  if (!output.includes(testCase.expectedSummary)) {
    problems.push(`missing expected summary line: "${testCase.expectedSummary}"`);
  }
  // Both jobs (test, validate) must succeed.
  const succeededCount = (output.match(/Job succeeded/g) ?? []).length;
  if (succeededCount < 2) {
    problems.push(
      `expected 2 "Job succeeded" markers, found ${succeededCount}`,
    );
  }
  if (/Job failed/.test(output)) {
    problems.push(`output contains "Job failed"`);
  }

  if (problems.length > 0) {
    failures++;
    console.error(`FAIL [${testCase.name}]:\n  - ${problems.join("\n  - ")}`);
  } else {
    console.log(`PASS [${testCase.name}] — ${testCase.expectedSummary}`);
  }

  rmSync(dir, { recursive: true, force: true });
}

console.log(`\n=== ${CASES.length - failures}/${CASES.length} act cases passed ===`);
console.log(`Full output saved to ${RESULT_FILE}`);
process.exit(failures === 0 ? 0 : 1);

